  async function ensureDefaults(){if(!client()||!biz()?.id)return;const {error}=await client().rpc('v55_seed_payroll_defaults',{p_business_id:biz().id});if(error)console.warn('Payroll defaults:',error.message)}
  async function load(){if(!client()||!biz()?.id)return;state.businessId=biz().id;await ensureDefaults();const c=client();const set=await c.from('payroll_settings').select('*').maybeSingle();state.settings=set.data||{country_code:'NZ',currency:appSettings().currency||'NZD',default_pay_frequency:'fortnightly',default_pay_day:5,default_weekly_hours:40,default_working_days:5,employee_prefix:'EMP'};const country=String(state.settings.country_code||'NZ').toUpperCase();let rules=await c.from('country_payroll_rules').select('*').eq('active',true).order('effective_from',{ascending:false});if(rules.error){console.warn('Country payroll rules fallback:',rules.error.message);rules=await c.from('payroll_country_rules').select('*').eq('active',true).order('effective_from',{ascending:false})}const allRules=rules.data||[];state.ruleCountries=[...new Set(allRules.map(r=>String(r.country_code||'').trim().toUpperCase()).filter(Boolean))].sort();state.countryRules=allRules.filter(r=>String(r.country_code||'').trim().toUpperCase()===country);const [emp,ts,tse,runs,re,rl,pay,leave,docs,edocs,jobs,customers]=await Promise.all([
    c.from('payroll_employees').select('*').order('last_name'),c.from('payroll_timesheets').select('*').order('work_date',{ascending:false}),c.from('payroll_timesheet_expenses').select('*').order('created_at'),c.from('payroll_pay_runs').select('*').order('pay_date',{ascending:false}),c.from('payroll_pay_run_employees').select('*'),c.from('payroll_pay_run_lines').select('*'),c.from('payroll_pay_items').select('*').eq('archived',false).order('item_type').order('name'),c.from('payroll_leave_types').select('*').eq('archived',false).order('name'),c.from('payroll_document_types').select('*').eq('archived',false).order('sort_order'),c.from('payroll_employee_documents').select('*').order('uploaded_at',{ascending:false}),c.from('job_costings').select('id,costing_number,customer_id,customer_name,job_description').order('created_at',{ascending:false}),c.from('customers').select('id,name').order('name')
  ]);state.employees=emp.data||[];state.timesheets=ts.data||[];state.timesheetExpenses=tse.data||[];state.runs=runs.data||[];state.runEmployees=re.data||[];state.runLines=rl.data||[];state.payItems=uniquePayItems(pay.data||[]);state.leaveTypes=leave.data||[];state.docTypes=docs.data||[];state.documents=edocs.data||[];state.jobs=jobs.data||[];state.customers=customers.data||[];state.loaded=true;renderAll()}

  function setTab(tab){state.activeTab=tab;document.querySelectorAll('[data-payroll-tab]').forEach(b=>b.classList.toggle('active',b.dataset.payrollTab===tab));document.querySelectorAll('.payroll-panel').forEach(p=>p.classList.toggle('active',p.id===`payroll-panel-${tab}`));if(tab==='employees')renderEmployees();if(tab==='timesheets')renderTimesheets();if(tab==='runs')renderRuns();if(tab==='newrun'){const ready=state.newRunInitialized&&$('prStart')?.value&&$('prEnd')?.value&&$('prPayDate')?.value;if(!ready){initialiseRun();state.newRunInitialized=true}else bindRunActionHandlers()}if(tab==='settings')renderSettings()}
