  function summary(){const active=state.employees.filter(e=>e.employment_status==='active'&&!e.archived).length, awaiting=state.timesheets.filter(t=>t.status==='submitted').length;$('payrollActiveCount').textContent=active;$('payrollAwaitingCount').textContent=awaiting;const next=state.runs.find(r=>r.status!=='finalised'&&r.pay_date>=today())?.pay_date;$('payrollNextPayDate').textContent=next?iso(next):'—'}
  function renderEmployees(){summary();if(!$('payrollEmployeeRows'))return;const q=($('payrollEmployeeSearch')?.value||'').toLowerCase(),status=$('payrollEmployeeStatus')?.value||'';const arr=state.employees.filter(e=>!e.archived&&(!status||e.employment_status===status)&&(!q||[displayName(e),e.job_title,e.email,e.employee_number].join(' ').toLowerCase().includes(q)));const rows=arr.map(e=>`<tr><td><strong>${esc(displayName(e))}</strong><small>${esc(e.employee_number)}</small></td><td>${esc(e.job_title||'—')}</td><td>${esc(human(e.employment_type))}</td><td>${esc(e.pay_type==='salary'?money(e.annual_salary)+'/yr':money(e.hourly_rate)+'/hr')}</td><td>${esc(human(e.pay_frequency))}</td><td><span class="badge payroll-status ${esc(e.employment_status)}">${esc(human(e.employment_status))}</span></td><td><div class="row-actions"><button class="secondary" data-pe-view="${e.id}">Edit</button><button class="danger" data-pe-delete="${e.id}">Delete</button>${e.employment_status!=='terminated'?`<button class="secondary" data-pe-term="${e.id}">Terminate</button>`:''}</div></td></tr>`).join('');$('payrollEmployeeRows').innerHTML=rows||'<tr><td colspan="7">No employees yet. Add your first employee to start using Payroll.</td></tr>';$('payrollEmployeeCards').innerHTML=arr.map(e=>`<div class="payroll-mobile-card"><strong>${esc(displayName(e))}</strong><span>${esc(e.job_title||'')}</span><small>${esc(human(e.employment_type))} · ${esc(employeeRate(e))} · ${esc(human(e.pay_frequency))}</small><span class="badge payroll-status ${esc(e.employment_status)}">${esc(human(e.employment_status))}</span><div class="row-actions"><button class="secondary" data-pe-view="${e.id}">Edit</button><button class="danger" data-pe-delete="${e.id}">Delete</button></div></div>`).join('');bindEmployeeRowActions()}
  function bindEmployeeRowActions(){document.querySelectorAll('[data-pe-view]').forEach(b=>b.onclick=()=>openEmployee(state.employees.find(e=>e.id===b.dataset.peView)));document.querySelectorAll('[data-pe-delete]').forEach(b=>b.onclick=()=>deleteEmployeeById(b.dataset.peDelete));document.querySelectorAll('[data-pe-term]').forEach(b=>b.onclick=async()=>{const e=state.employees.find(x=>x.id===b.dataset.peTerm);if(!e)return;const reason=prompt(`Termination reason for ${displayName(e)} (optional):`,'')??null;if(reason===null)return;const end=prompt('Termination date (YYYY-MM-DD):',today());if(!end)return;const {error}=await client().from('payroll_employees').update({employment_status:'terminated',end_date:end,termination_reason:reason,updated_at:new Date().toISOString(),updated_by:window.SAAS.state.user.id}).eq('id',e.id);if(error)return toast(error.message);await audit('employee',e.id,'terminated',e,{...e,employment_status:'terminated',end_date:end});await load();toast('Employee terminated. Payroll history has been retained.')})}

  async function nextEmployeeNo(){const prefix=(state.settings?.employee_prefix||'EMP').toUpperCase();let max=0;state.employees.forEach(e=>{const m=String(e.employee_number||'').match(new RegExp(`^${prefix}-(\\d+)$`));if(m)max=Math.max(max,+m[1])});return `${prefix}-${String(max+1).padStart(4,'0')}`}
  async function nextRunNo(){
    /* Read the current business's pay-run numbers directly from Supabase so a
       stale in-memory run list can never generate a duplicate number. */
    const res=await client().from('payroll_pay_runs').select('pay_run_number').eq('business_id',state.businessId);
    if(res.error)throw new Error(`Could not determine the next pay run number: ${res.error.message}`);
    const existing=(res.data||[]).map(r=>String(r.pay_run_number||'').trim()).filter(Boolean);
    let prefix='PAY-',width=4,max=0;
    for(const value of existing){
      const m=value.match(/^(.*?)(\d+)$/);
      if(!m)continue;
      const n=Number(m[2]);
      if(!Number.isFinite(n))continue;
      if(n>=max){max=n;prefix=m[1]||'PAY-';width=Math.max(4,m[2].length)}
    }
    let candidate=`${prefix}${String(max+1).padStart(width,'0')}`;
    while(existing.includes(candidate)){
      max+=1;
      candidate=`${prefix}${String(max+1).padStart(width,'0')}`;
    }
    return candidate;
  }
