  async function deleteEmployeeById(id){const e=state.employees.find(x=>x.id===id);if(!e)return;const hasHistory=state.timesheets.some(x=>x.employee_id===id)||state.runEmployees.some(x=>x.employee_id===id)||state.documents.some(x=>x.employee_id===id);const {data:leaveRows}=await client().from('payroll_leave_transactions').select('id').eq('employee_id',id).limit(1);if(hasHistory||(leaveRows||[]).length)return toast('This employee has payroll, timesheet, document or leave history and cannot be permanently deleted. Use Terminate or set the employee Inactive instead.');if(!confirm(`Permanently delete ${displayName(e)}? This is only allowed because no payroll history exists.`))return;const {error}=await client().from('payroll_employees').delete().eq('id',id);if(error)return toast(error.message);close('payrollEmployeeModal');await load();toast('Employee deleted.')}

  async function addDocument(){const employeeId=$('payrollEmployeeId').value,file=$('peDocumentFile').files?.[0];if(!employeeId)return toast('Save the employee before adding documents.');if(!file)return toast('Choose a document first.');if(file.size>10*1024*1024)return toast('Document must be 10 MB or smaller.');const safe=file.name.replace(/[^a-zA-Z0-9._-]+/g,'_'),path=`${state.businessId}/${employeeId}/${crypto.randomUUID()}-${safe}`;const {error}=await client().storage.from('payroll-documents').upload(path,file,{contentType:file.type,upsert:false});if(error)return toast(error.message);const {data,error:dbErr}=await client().from('payroll_employee_documents').insert({business_id:state.businessId,employee_id:employeeId,document_type_id:$('peDocumentType').value||null,document_name:$('peDocumentName').value.trim()||file.name,storage_path:path,original_filename:file.name,mime_type:file.type,file_size:file.size,expiry_date:$('peDocumentExpiry').value||null,notes:$('peDocumentNotes').value.trim()||null,uploaded_by:window.SAAS.state.user.id}).select().single();if(dbErr){await client().storage.from('payroll-documents').remove([path]);return toast(dbErr.message)}state.documents.unshift(data);$('peDocumentFile').value='';$('peDocumentName').value='';renderEmployeeDocs(employeeId);toast('Document uploaded')}
  async function viewDocument(id){const d=state.documents.find(x=>x.id===id);if(!d)return;const {data,error}=await client().storage.from('payroll-documents').createSignedUrl(d.storage_path,120);if(error)return toast(error.message);window.open(data.signedUrl,'_blank','noopener')}
  async function deleteDocument(id){const d=state.documents.find(x=>x.id===id);if(!d||!confirm('Delete this employee document?'))return;const {error}=await client().storage.from('payroll-documents').remove([d.storage_path]);if(error)return toast(error.message);await client().from('payroll_employee_documents').delete().eq('id',id);state.documents=state.documents.filter(x=>x.id!==id);renderEmployeeDocs(d.employee_id);toast('Document deleted')}

  function populateTimesheetSelectors(){const options=state.employees.filter(e=>e.employment_status==='active'&&!e.archived).map(e=>`<option value="${e.id}">${esc(displayName(e))}</option>`).join('');$('ptEmployee').innerHTML=options;$('payrollTimesheetEmployee').innerHTML='<option value="">All employees</option>'+options;const jobs=state.jobs.map(j=>`<option value="${j.id}">${esc(j.costing_number+' · '+(j.job_description||j.customer_name||'Job'))}</option>`).join('');$('ptJob').innerHTML='<option value="">Not linked to a job</option>'+jobs}
  function calcHours(){const s=$('ptStart').value,f=$('ptFinish').value,b=num($('ptBreak').value);if(!s||!f){$('ptTotal').value='0.00';return 0}const [sh,sm]=s.split(':').map(Number),[fh,fm]=f.split(':').map(Number);let mins=(fh*60+fm)-(sh*60+sm);if(mins<0)mins+=1440;if(b>mins){$('ptTotal').value='0.00';return 0}const h=Math.max(0,(mins-b)/60);$('ptTotal').value=h.toFixed(2);return h}
  function timesheetExpenseRows(){return [...document.querySelectorAll('#ptExpenseRows .timesheet-expense-row')].map(r=>({description:r.querySelector('[data-exp-description]').value.trim(),amount:num(r.querySelector('[data-exp-amount]').value)})).filter(x=>x.description||x.amount>0)}
  function refreshTimesheetExpenseTotal(){const total=timesheetExpenseRows().reduce((a,x)=>a+num(x.amount),0);if($('ptExpenseTotal'))$('ptExpenseTotal').textContent=money(total)}
  function addTimesheetExpenseRow(exp=null){const wrap=document.createElement('div');wrap.className='timesheet-expense-row';wrap.innerHTML=`<label>Description<input data-exp-description placeholder="Travel, parking, mileage…" value="${esc(exp?.description||'')}"></label><label>Amount<input data-exp-amount type="number" min="0" step="0.01" value="${exp?num(exp.amount).toFixed(2):''}" placeholder="0.00"></label><button class="danger compact-btn" type="button" data-exp-remove>Remove</button>`;$('ptExpenseRows').appendChild(wrap);wrap.querySelector('[data-exp-remove]').onclick=()=>{wrap.remove();refreshTimesheetExpenseTotal()};wrap.querySelector('[data-exp-amount]').oninput=refreshTimesheetExpenseTotal;refreshTimesheetExpenseTotal()}
  function openTimesheet(t=null){populateTimesheetSelectors();$('ptId').value=t?.id||'';$('payrollTimesheetTitle').textContent=t?'Edit Timesheet':'Add Time';$('ptEmployee').value=t?.employee_id||state.employees.find(e=>e.employment_status==='active')?.id||'';$('ptDate').value=t?.work_date||today();$('ptJob').value=t?.job_costing_id||'';$('ptStart').value=t?.start_time?.slice(0,5)||'09:00';$('ptFinish').value=t?.finish_time?.slice(0,5)||'17:00';$('ptBreak').value=t?.break_minutes??30;$('ptPayType').value=t?.pay_type||'ordinary';$('ptNotes').value=t?.notes||'';$('ptStatus').value=t?.status||'draft';$('ptExpenseRows').innerHTML='';(t?state.timesheetExpenses.filter(x=>x.timesheet_id===t.id):[]).forEach(addTimesheetExpenseRow);$('payrollDeleteTimesheet').hidden=!t;calcHours();refreshTimesheetExpenseTotal();open('payrollTimesheetModal')}
  async function saveTimesheet(){const total=calcHours();if(!$('ptEmployee').value||!$('ptDate').value)return toast('Employee and date are required.');if(total<=0)return toast('Finish time and break must result in more than 0 hours.');const expenses=timesheetExpenseRows();if(expenses.some(x=>!x.description||x.amount<=0))return toast('Each expense needs a description and an amount greater than zero.');const job=state.jobs.find(j=>j.id===$('ptJob').value),payload={business_id:state.businessId,employee_id:$('ptEmployee').value,work_date:$('ptDate').value,job_costing_id:$('ptJob').value||null,customer_id:job?.customer_id||null,start_time:$('ptStart').value||null,finish_time:$('ptFinish').value||null,break_minutes:num($('ptBreak').value),total_hours:total,pay_type:$('ptPayType').value,notes:$('ptNotes').value.trim()||null,status:$('ptStatus').value,submitted_at:$('ptStatus').value==='submitted'?new Date().toISOString():null,approved_at:$('ptStatus').value==='approved'?new Date().toISOString():null,approved_by:$('ptStatus').value==='approved'?window.SAAS.state.user.id:null,updated_at:new Date().toISOString(),updated_by:window.SAAS.state.user.id};const id=$('ptId').value,old=id?state.timesheets.find(t=>t.id===id):null;const res=id?await client().from('payroll_timesheets').update(payload).eq('id',id).select().single():await client().from('payroll_timesheets').insert({...payload,created_by:window.SAAS.state.user.id}).select().single();if(res.error)return toast(res.error.message);await client().from('payroll_timesheet_expenses').delete().eq('timesheet_id',res.data.id);if(expenses.length){const rows=expenses.map(x=>({business_id:state.businessId,timesheet_id:res.data.id,employee_id:res.data.employee_id,job_costing_id:res.data.job_costing_id||null,description:x.description,amount:trunc2(x.amount),taxable:false,created_by:window.SAAS.state.user.id}));const er=await client().from('payroll_timesheet_expenses').insert(rows);if(er.error)return toast('Timesheet saved, but expenses could not be saved: '+er.error.message)}await audit('timesheet',res.data.id,id?'updated':'created',old,{...res.data,expenses});close('payrollTimesheetModal');await load();toast('Timesheet saved')}
  async function deleteTimesheet(id){const t=state.timesheets.find(x=>x.id===id);if(!t)return;if(!confirm('Permanently delete this timesheet entry and its attached employee expenses?'))return;const {error}=await client().from('payroll_timesheets').delete().eq('id',id);if(error)return toast(error.message);await audit('timesheet',id,'deleted',t,null);close('payrollTimesheetModal');await load();toast('Timesheet deleted.')}
  function renderTimesheets(){if(!$('payrollTimesheetRows'))return;populateTimesheetSelectors();if(!$('payrollTimesheetFrom').value){$('payrollTimesheetFrom').value=addDays(today(),-14);$('payrollTimesheetTo').value=today()}const from=$('payrollTimesheetFrom').value,to=$('payrollTimesheetTo').value,emp=$('payrollTimesheetEmployee').value,status=$('payrollTimesheetStatus').value;const em=new Map(state.employees.map(e=>[e.id,displayName(e)])),jm=new Map(state.jobs.map(j=>[j.id,j.costing_number+' · '+(j.job_description||j.customer_name||'Job')]));const arr=state.timesheets.filter(t=>(!from||t.work_date>=from)&&(!to||t.work_date<=to)&&(!emp||t.employee_id===emp)&&(!status||t.status===status));$('payrollTimesheetRows').innerHTML=arr.map(t=>`<tr><td>${t.status==='submitted'?`<input type="checkbox" data-ts-select="${t.id}">`:''}</td><td>${iso(t.work_date)}</td><td>${esc(em.get(t.employee_id)||'Employee')}</td><td>${esc(jm.get(t.job_costing_id)||'—')}</td><td><strong>${num(t.total_hours).toFixed(2)}</strong>${state.timesheetExpenses.some(x=>x.timesheet_id===t.id)?`<small>Expenses ${money(state.timesheetExpenses.filter(x=>x.timesheet_id===t.id).reduce((a,x)=>a+num(x.amount),0))}</small>`:''}</td><td><span class="badge payroll-status ${t.status}">${esc(human(t.status))}</span></td><td><div class="row-actions"><button class="secondary" data-ts-edit="${t.id}">View / Edit</button>${t.status==='submitted'?`<button class="primary" data-ts-approve="${t.id}">Approve</button>`:''}<button class="danger" data-ts-delete="${t.id}">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="7">No timesheets for this period.</td></tr>';$('payrollTimesheetCards').innerHTML=arr.map(t=>`<div class="payroll-mobile-card"><strong>${esc(em.get(t.employee_id)||'Employee')}</strong><span>${iso(t.work_date)} · ${num(t.total_hours).toFixed(2)} hours</span><small>${esc(jm.get(t.job_costing_id)||'No job')}${state.timesheetExpenses.some(x=>x.timesheet_id===t.id)?' · Expenses '+money(state.timesheetExpenses.filter(x=>x.timesheet_id===t.id).reduce((a,x)=>a+num(x.amount),0)):''}</small><span class="badge payroll-status ${t.status}">${esc(human(t.status))}</span><button class="secondary" data-ts-edit="${t.id}">View</button>${t.status==='submitted'?`<button class="primary" data-ts-approve="${t.id}">Approve</button>`:''}</div>`).join('');document.querySelectorAll('[data-ts-edit]').forEach(b=>b.onclick=()=>openTimesheet(state.timesheets.find(t=>t.id===b.dataset.tsEdit)));document.querySelectorAll('[data-ts-approve]').forEach(b=>b.onclick=()=>approveTimesheets([b.dataset.tsApprove]));document.querySelectorAll('[data-ts-delete]').forEach(b=>b.onclick=()=>deleteTimesheet(b.dataset.tsDelete))}
  async function approveTimesheets(ids){if(!ids.length)return toast('Select submitted timesheets first.');const now=new Date().toISOString();const {error}=await client().from('payroll_timesheets').update({status:'approved',approved_at:now,approved_by:window.SAAS.state.user.id,updated_at:now,updated_by:window.SAAS.state.user.id}).in('id',ids).eq('status','submitted');if(error)return toast(error.message);for(const id of ids)await audit('timesheet',id,'approved',null,{status:'approved'});await load();toast(`${ids.length} timesheet${ids.length===1?'':'s'} approved`)}

  // Country rules are effective-dated in Supabase. Finalised runs snapshot the exact rules used.
  function rule(type,key,date=today()){return state.countryRules.find(r=>r.rule_type===type&&r.rule_key===key&&r.effective_from<=date&&(!r.effective_to||r.effective_to>=date))||null}
  function requiredRule(type,key,date=today()){const r=rule(type,key,date);if(!r)throw new Error(`Payroll tax rule missing for ${String(state.settings?.country_code||'').toUpperCase()}: ${type}.${key} on ${date}. Ask the Super Admin to configure Country Payroll Tax Rules.`);return r}
  function ruleNum(type,key,date,fallback=null){const r=rule(type,key,date);if(r?.numeric_value!=null)return num(r.numeric_value);if(fallback!==null)return num(fallback);throw new Error(`Payroll tax rule ${type}.${key} has no numeric value for ${date}.`)}
  function ruleJson(type,key,date,fallback=null){const r=rule(type,key,date);if(r?.json_value!=null)return r.json_value;if(fallback!==null)return fallback;throw new Error(`Payroll tax rule ${type}.${key} has no JSON value for ${date}.`)}
  function activeRuleSnapshot(date){return state.countryRules.filter(r=>r.effective_from<=date&&(!r.effective_to||r.effective_to>=date)).map(r=>({type:r.rule_type,key:r.rule_key,numeric_value:r.numeric_value,text_value:r.text_value,json_value:r.json_value,effective_from:r.effective_from,effective_to:r.effective_to,source_note:r.source_note}))}
  function annualIncomeTax(a,date){a=Math.max(0,a);const brackets=ruleJson('paye','annual_brackets',date);let tax=0,lower=0;for(const b of brackets){const upper=b.max==null?a:Math.min(a,num(b.max));if(upper>lower)tax+=(upper-lower)*num(b.rate);if(b.max==null||a<=num(b.max))break;lower=num(b.max)}return tax}
  function ietc(a,date){const r=ruleJson('paye','ietc',date);if(a<num(r.min_income)||a>=num(r.max_income))return 0;if(a<=num(r.full_to))return num(r.credit);return Math.max(0,num(r.credit)-(a-num(r.full_to))*num(r.abatement))}
  function esctRate(a,date){const rows=ruleJson('esct','annual_rates',date);return num((rows.find(x=>x.max==null||a<=num(x.max))||rows[rows.length-1]).rate)}
  function taxCodeProfiles(date=today()){const value=ruleJson('paye','tax_codes',date);if(Array.isArray(value))return value;if(typeof value==='string'){try{const parsed=JSON.parse(value);if(Array.isArray(parsed))return parsed}catch{}}throw new Error(`Payroll tax rule paye.tax_codes is not a valid tax-code list for ${date}. Ask the Super Admin to check Country Payroll Tax Rules.`)}
  function taxCodeProfile(code,date=today()){const normalized=String(code||'').toUpperCase().replace(/\s+/g,' ').trim(),profiles=taxCodeProfiles(date);return profiles.find(x=>String(x?.code||'').toUpperCase()===normalized)||null}
  function populateTaxCodeOptions(selected=''){const el=$('peTaxCode');if(!el)return;let profiles=[];try{profiles=taxCodeProfiles(today())}catch{}const current=selected||el.value||profiles[0]?.code||'';el.innerHTML=profiles.map(x=>`<option value="${esc(x.code)}">${esc(x.label||x.code)}</option>`).join('');if(current&&profiles.some(x=>x.code===current))el.value=current}
  function payeFor(e,gross,frequency,payDate=today()){const pay=Math.floor(Math.max(0,gross)),ppy=paysPerYear(frequency),code=String(e.tax_code||'').toUpperCase().replace(/\s+/g,' ').trim(),profile=taxCodeProfile(code,payDate);if(!profile)throw new Error(`Tax code ${code||'(blank)'} is not configured for ${String(state.settings?.country_code||'').toUpperCase()} on ${payDate}.`);const acc=ruleNum('acc','earners_levy_rate',payDate,0)/100,accMax=ruleNum('acc','max_earnings',payDate,0),secondary=ruleJson('paye','secondary_rates',payDate,{});let paye=0;if(profile.mode==='secondary'){const key=profile.secondary_key||code;if(!Object.prototype.hasOwnProperty.call(secondary,key))throw new Error(`Secondary tax rate ${key} is not configured for ${payDate}.`);paye=pay*num(secondary[key])}else{const annual=pay*ppy,tax=annualIncomeTax(annual,payDate),levy=Math.min(annual,accMax)*acc,credit=profile.ietc?ietc(annual,payDate):0,weekly=trunc2((tax+levy-credit)/52);paye=weekly*52/ppy}paye=trunc2(paye);let student=0;const sl=!!e.student_loan||!!profile.student_loan;if(sl){const slRate=ruleNum('student_loan','standard_rate',payDate)/100,slThreshold=ruleNum('student_loan','annual_threshold',payDate);if(profile.student_loan_threshold!==false){const threshold=slThreshold/ppy;student=pay>threshold?trunc2((pay-threshold)*slRate):0}else student=trunc2(pay*slRate)}return{paye,student}}
  function salaryPeriod(e,f){return num(e.annual_salary)/paysPerYear(f)}
  function finalisedRunIdSet(){return new Set(state.runs.filter(r=>r.status==='finalised').map(r=>r.id))}
  function finalisedRunEmployeeIdSet(){const runIds=finalisedRunIdSet();return new Set(state.runEmployees.filter(x=>runIds.has(x.pay_run_id)).map(x=>x.id))}
  function paidTimesheetIdSet(){const preIds=finalisedRunEmployeeIdSet();return new Set(state.runLines.filter(l=>preIds.has(l.pay_run_employee_id)&&l.timesheet_id&&['ordinary','overtime'].includes(l.line_type)).map(l=>l.timesheet_id))}
  function matchingFinalisedEmployeeRuns(employeeId,run){return state.runs.filter(r=>r.status==='finalised'&&r.period_start===run.period_start&&r.period_end===run.period_end&&state.runEmployees.some(x=>x.pay_run_id===r.id&&x.employee_id===employeeId))}
  function legacyFinalisedPeriodRun(employeeId,run){return matchingFinalisedEmployeeRuns(employeeId,run).find(r=>{const preIds=new Set(state.runEmployees.filter(x=>x.pay_run_id===r.id&&x.employee_id===employeeId).map(x=>x.id));const earningLines=state.runLines.filter(l=>preIds.has(l.pay_run_employee_id)&&['ordinary','overtime'].includes(l.line_type));return !earningLines.length||earningLines.every(l=>!l.timesheet_id)})||null}
  function employeeBlockedByFinalisedPeriod(e,run){if(e.pay_type==='salary')return matchingFinalisedEmployeeRuns(e.id,run)[0]||null;return legacyFinalisedPeriodRun(e.id,run)}
  function calcEmployee(e,run){const paid=paidTimesheetIdSet(),blocked=employeeBlockedByFinalisedPeriod(e,run),ts=blocked?[]:state.timesheets.filter(t=>t.employee_id===e.id&&t.status==='approved'&&t.work_date>=run.period_start&&t.work_date<=run.period_end&&!paid.has(t.id)),ordinaryH=ts.filter(t=>t.pay_type!=='overtime').reduce((a,t)=>a+num(t.total_hours),0),overtimeH=ts.filter(t=>t.pay_type==='overtime').reduce((a,t)=>a+num(t.total_hours),0);const ordinary=e.pay_type==='salary'&&!blocked?salaryPeriod(e,run.pay_frequency):ordinaryH*num(e.hourly_rate),overtime=e.pay_type==='hourly'?overtimeH*num(e.hourly_rate)*num(e.overtime_multiplier||1.5):0,holiday=e.annual_holiday_method==='payg'?(ordinary+overtime)*num(e.holiday_pay_rate)/100:0;const expenseLines=ts.flatMap(t=>state.timesheetExpenses.filter(x=>x.timesheet_id===t.id).map(x=>({line_type:'reimbursement',description:x.description||'Timesheet expense',quantity:1,rate:num(x.amount),amount:num(x.amount),taxable:false,job_costing_id:t.job_costing_id||x.job_costing_id||null,timesheet_id:t.id})));return applyManual({employee:e,hours:ordinaryH+overtimeH,ordinaryH,overtimeH,rate:num(e.hourly_rate),ordinary,overtime,holiday,timesheets:ts,manualLines:expenseLines,duplicateBlockedBy:blocked||null},run)}
  function applyManual(x,run){const lines=x.manualLines||[],earnings=lines.filter(l=>['earning','allowance'].includes(l.line_type)),taxableAllowances=earnings.filter(l=>l.line_type==='allowance'&&l.taxable!==false).reduce((a,l)=>a+num(l.amount),0),taxFreeAllowances=earnings.filter(l=>l.line_type==='allowance'&&l.taxable===false).reduce((a,l)=>a+num(l.amount),0),allowances=taxableAllowances+taxFreeAllowances,extraEarnings=earnings.filter(l=>l.line_type==='earning').reduce((a,l)=>a+num(l.amount),0),reimbursements=lines.filter(l=>l.line_type==='reimbursement').reduce((a,l)=>a+num(l.amount),0),otherDeductions=lines.filter(l=>l.line_type==='deduction').reduce((a,l)=>a+num(l.amount),0),otherEmployer=lines.filter(l=>l.line_type==='contribution').reduce((a,l)=>a+num(l.amount),0),gross=x.ordinary+x.overtime+x.holiday+taxableAllowances+extraEarnings,taxableBase=x.ordinary+x.overtime+x.holiday+earnings.filter(l=>l.taxable!==false).reduce((a,l)=>a+num(l.amount),0),td=payeFor(x.employee,taxableBase,run.pay_frequency,run.pay_date),kiwiActive=x.employee.kiwisaver_status==='enrolled',kiwiEmp=kiwiActive?trunc2(taxableBase*num(x.employee.kiwisaver_employee_rate)/100):0,employerGross=kiwiActive?trunc2(taxableBase*num(x.employee.kiwisaver_employer_rate)/100):0,annualBasis=x.employee.pay_type==='salary'?num(x.employee.annual_salary):num(x.employee.hourly_rate)*num(x.employee.standard_weekly_hours)*52,esct=trunc2(employerGross*esctRate(annualBasis+employerGross*paysPerYear(run.pay_frequency),run.pay_date)),employerNet=trunc2(employerGross-esct),ded=trunc2(td.paye+td.student+kiwiEmp+otherDeductions),net=trunc2(gross-ded+taxFreeAllowances+reimbursements),cost=trunc2(gross+taxFreeAllowances+employerGross+otherEmployer+reimbursements);return{...x,allowances,taxableAllowances,taxFreeAllowances,reimbursements,extraEarnings,otherDeductions,otherEmployer,gross,paye:td.paye,student:td.student,kiwiEmp,deductions:ded,net,employerGross,esct,employerNet,cost}}

  function currentRunDef(){return{pay_frequency:$('prFrequency').value,period_start:$('prStart').value,period_end:$('prEnd').value,pay_date:$('prPayDate').value}}
  function selectedRunCalc(){const ids=new Set(state.runSelectedIds||[]);return state.runCalc.filter(x=>ids.has(x.employee.id))}
  function setAllRunEmployees(selected){state.runSelectedIds=selected?state.runCalc.map(x=>x.employee.id):[];renderRunCalc(state.runLocked)}
  function toggleRunEmployee(id,selected){const s=new Set(state.runSelectedIds||[]);selected?s.add(id):s.delete(id);state.runSelectedIds=[...s];renderRunCalc(state.runLocked)}
  function toggleRunEmployeeDetails(id){const s=new Set(state.runExpandedIds||[]);s.has(id)?s.delete(id):s.add(id);state.runExpandedIds=[...s];renderRunCalc(state.runLocked)}
  function removeRunAdjustment(employeeId,lineIndex){if(state.runLocked)return;const x=state.runCalc.find(x=>x.employee.id===employeeId);if(!x)return;x.manualLines=(x.manualLines||[]).filter((_,i)=>i!==lineIndex);const idx=state.runCalc.findIndex(y=>y.employee.id===employeeId);state.runCalc[idx]=applyManual(x,currentRunDef());renderRunCalc(false);renderQuickPayItems()}
  function runJobLabel(t){const j=state.jobs.find(j=>j.id===t.job_costing_id);return j?(j.costing_number+' · '+(j.job_description||j.customer_name||'Job')):(t.job_costing_id?'Linked job':'General / No Job')}
